          "lines": {
            "Mio": "Suggests a flat fee is the safest bet for the budget.",
            "Jonathan": "Agrees that simplicity fosters a better atmosphere.",
            "Takumi": "Reluctantly admits that administrative collapse helps no one.",
            "Toshio": "Urges a vote for the most efficient option.",
            "Kenji": "Still hopes for a more flexible approach but sees the logic."
          }
        },
        {
